func NewWikiValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (WikiValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing WikiValue Attribute Value",
				"While creating a WikiValue value, a missing attribute value was detected. "+
					"A WikiValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("WikiValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid WikiValue Attribute Type",
				"While creating a WikiValue value, an invalid attribute value was detected. "+
					"A WikiValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("WikiValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("WikiValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra WikiValue Attribute Value",
				"While creating a WikiValue value, an extra attribute value was detected. "+
					"A WikiValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra WikiValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewWikiValueUnknown(), diags
	}

	enabledAttribute, ok := attributes["enabled"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`enabled is missing from object`)

		return NewWikiValueUnknown(), diags
	}

	enabledVal, ok := enabledAttribute.(basetypes.BoolValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`enabled expected to be basetypes.BoolValue, was: %T`, enabledAttribute))
	}

	pageCountAttribute, ok := attributes["page_count"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`page_count is missing from object`)

		return NewWikiValueUnknown(), diags
	}

	pageCountVal, ok := pageCountAttribute.(basetypes.Int64Value)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`page_count expected to be basetypes.Int64Value, was: %T`, pageCountAttribute))
	}

	if diags.HasError() {
		return NewWikiValueUnknown(), diags
	}

	return WikiValue{
		Enabled:   enabledVal,
		PageCount: pageCountVal,
		state:     attr.ValueStateKnown,
	}, diags
}

